<?phpnamespace App\Models;use Database\Factories\UserFactory;use Illuminate\Database\Eloquent\Concerns\HasUuids;use Illuminate\Database\Eloquent\Factories\HasFactory;use Illuminate\Database\Eloquent\Relations\HasMany;use Illuminate\Foundation\Auth\User as Authenticatable;use Illuminate\Notifications\Notifiable;use Laravel\Sanctum\HasApiTokens;use Laravel\Sanctum\PersonalAccessToken;class User extends Authenticatable{    /** @use HasFactory<UserFactory> */    use HasFactory, Notifiable, HasUuids, HasApiTokens;    /**     * The primary key associated with the table.     * @var string     */    protected $primaryKey = 'uuid';    /**     * Indicates if the IDs are auto-incrementing.     * @var bool     */    public $incrementing = false;    /**     * The "type" of the primary key ID.     * @var string     */    protected $keyType = 'string';    /**     * The attributes that are mass assignable.     * @var list<string>     */    protected $fillable = [        'first_name',        'last_name',        'email',        'private_email',        'password',        'pesel',    ];    /**     * The attributes that should be hidden for serialization.     * @var list<string>     */    protected $hidden = [        'password',        'pesel',        'remember_token',    ];    /**     * @param string $token     * @return User|null     */    public static function whereToken(string $token): ?self    {        $accessToken = PersonalAccessToken::findToken($token);        if (is_null($accessToken)) {            return null;        }        return $accessToken->tokenable;    }    /**     * Get the attributes that should be cast.     * @return array<string, string>     */    protected function casts(): array    {        return [            'email_verified_at' => 'datetime',            'private_email_verified_at' => 'datetime',            'password' => 'hashed',        ];    }    /**     * @return string     */    public function getName(): string    {        $firstName = $this->firstName;        $lastName = $this->lastName;        return "$firstName $lastName";    }    /**     * @return HasMany     */    public function jobPositions(): HasMany    {        return $this->hasMany(JobPosition::class, 'user_uuid', 'uuid');    }}